declare_lint ! { #[doc = " The `special_module_name` lint detects module"] #[doc = " declarations for files that have a special meaning."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust,compile_fail"] #[doc = " mod lib;"] #[doc = ""] #[doc = " fn main() {"] #[doc = "     lib::run();"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " Cargo recognizes `lib.rs` and `main.rs` as the root of a"] #[doc = " library or binary crate, so declaring them as modules"] #[doc = " will lead to miscompilation of the crate unless configured"] #[doc = " explicitly."] #[doc = ""] #[doc = " To access a library from a binary target within the same crate,"] #[doc = " use `your_crate_name::` as the path instead of `lib::`:"] #[doc = ""] #[doc = " ```rust,compile_fail"] #[doc = " // bar/src/lib.rs"] #[doc = " fn run() {"] #[doc = "     // ..."] #[doc = " }"] #[doc = ""] #[doc = " // bar/src/main.rs"] #[doc = " fn main() {"] #[doc = "     bar::run();"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Binary targets cannot be used as libraries and so declaring"] #[doc = " one as a module is not allowed."] pub SPECIAL_MODULE_NAME , Warn , "module declarations for files with a special meaning" , }